  if(current.group){const minutes=Math.round(delta/current.length*(current.range.end-current.range.start)/15)*15;const issue=selectionMoveError(current.group,minutes);if(issue){setError(issue);return}const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('.schedule-track')?.dataset.technician||current.sourceTechnician;const drafts=selectionDraft(current.group,minutes,current.sourceTechnician,target);gestureRef.current={...current,delta:minutes,targetTechnician:target,drafts,draft:drafts.find(a=>a.id===current.original.id),moved:true};setGesture(gestureRef.current);return}
